function [ys_, params, info] = SOE_simulations_pf_steadystate2(ys_, exo_, params)
% Steady state generated by Dynare preprocessor
    info = 0;
    tau_k_ss=params(36);
    tau_n_ss=params(37);
    tau_c_ss=params(38);
    params(17)=params(45)^params(3)/params(49)/params(18);
    params(67)=(1-params(13))*params(55)+params(13)*params(56);
    q_ss=params(57);
    rK_ss=(q_ss*(params(45)^params(3)/params(17)-1+params(6))-tau_k_ss*params(6))/(1-tau_k_ss);
    pH_ss=params(57)*(1/(1-params(8))*(1-params(8)*(1/params(57))^(1-params(7))))^(1/(1-params(7)));
    params(59)=params(58)*(1-(1-params(6))/params(45))/(1-(1-params(20))/params(45));
    yH_ss=(params(44)*(pH_ss*params(59)*params(5)/rK_ss)^params(15)*(pH_ss*params(5)/rK_ss)^params(5)*(params(45)*params(67))^(1-params(5)-params(15)))^(1/(1-params(5)-params(15)));
    k_ss=params(45)*pH_ss*params(5)*yH_ss/rK_ss;
    k_g_ss=params(59)*k_ss;
    g_i_ss=(1-(1-params(20))/params(45))*k_g_ss;
    k_o_ss=k_ss/(1-params(13));
    i_o_ss=(1-(1-params(6))/params(45))*k_o_ss;
    i_ss=(1-params(13))*i_o_ss;
    w_ss=yH_ss*pH_ss*(1-params(5)-params(15))/params(67);
    params(63)=pH_ss*yH_ss/(1-params(51));
    params(47)=params(51)*params(63)/params(68);
    g_c_ss=params(63)*params(52)/params(57);
    params(64)=params(63)*params(60);
    params(65)=params(63)*params(61);
    f_star_o_ss=params(65)/(1-params(13));
    params(66)=params(47)*params(68)*(1-params(9))-(1-params(49)*params(18)/params(45))*(params(64)+params(65));
    params(62)=(params(64)+params(65))/params(63);
    c_ss=(params(63)-params(66))/params(57)-i_ss-g_c_ss-g_i_ss;
    yC_ss=g_i_ss+g_c_ss+i_ss+c_ss;
    xF_ss=yC_ss*params(8)*(1/params(57))^(-params(7));
    xH_ss=yC_ss*(1-params(8))*(pH_ss/params(57))^(-params(7));
    yF_ss=xF_ss;
    xHstar_ss=(yF_ss+params(66)-params(68)*params(47))/pH_ss;
    params(22)=xHstar_ss/(pH_ss^(-params(14))*params(50));
    pi_ss=yH_ss*pH_ss*params(15);
    tr_ss=params(63)*params(53);
    params(54)=(-(params(64)+params(47)*params(68)*params(9)+params(55)*(1-params(13))*tau_n_ss*w_ss+k_ss*tau_k_ss*(rK_ss-params(6))/params(45)+c_ss*tau_c_ss*params(57)-params(57)*g_c_ss-params(57)*g_i_ss-params(64)*params(49)*params(18)/params(45)-tr_ss))/(1-params(13));
    tr_o_ss=tr_ss*(1-params(19))/(1-params(13));
    tr_r_ss=tr_ss*params(19)/params(13);
    c_r_ss=(tr_r_ss+params(56)*w_ss)/(params(57)*(1+tau_c_ss));
    c_o_ss=(c_ss-params(13)*c_r_ss)/(1-params(13));
    c_hat_o_ss=((1-params(12))^(1/params(11))*(c_o_ss-c_o_ss*params(1)/params(45))^((params(11)-1)/params(11))+params(12)^(1/params(11))*g_c_ss^((params(11)-1)/params(11)))^(params(11)/(params(11)-1));
    c_hat_r_ss=(params(12)^(1/params(11))*g_c_ss^((params(11)-1)/params(11))+(1-params(12))^(1/params(11))*(c_r_ss-c_r_ss*params(1)/params(45))^((params(11)-1)/params(11)))^(params(11)/(params(11)-1));
    chitil_o_ss=c_hat_o_ss^params(3);
    chitil_r_ss=c_hat_r_ss^params(3);
    Theta_o_ss=1;
    Theta_r_ss=1;
    lam_o_ss=c_hat_o_ss^(-params(3))/(params(57)*(1+tau_c_ss))*((1-params(12))*c_hat_o_ss/(c_o_ss-c_o_ss*params(1)/params(45)))^(1/params(11));
    lam_r_ss=c_hat_r_ss^(-params(3))/(params(57)*(1+tau_c_ss))*((1-params(12))*c_hat_r_ss/(c_r_ss-c_r_ss*params(1)/params(45)))^(1/params(11));
    params(41)=w_ss*lam_o_ss*(1-tau_n_ss)/params(55)^params(4);
    params(42)=w_ss*lam_r_ss/params(56)^params(4);
    gdp_ss=params(63)/params(57);
    debt_agg_y_ss=(params(64)+params(65))/(params(63)*4);
    capital_agg_ss=(k_g_ss/params(45))^params(15)*(k_ss/params(45))^params(5);
    t_revenue_ss=c_ss*tau_c_ss*params(57)+params(55)*(1-params(13))*tau_n_ss*w_ss+k_ss*tau_k_ss*(rK_ss-params(6))/params(45)+(1-params(13))*params(54);
    params(48)=params(47)*params(68)*params(9);
    revenue_ss=t_revenue_ss+params(48);
    spending_ss=tr_ss+params(57)*g_c_ss+params(57)*g_i_ss;
    b_y_ss=params(64)/(params(63)*4);
    f_y_ss=params(65)/(params(63)*4);
    g_c_y_ss=g_c_ss/gdp_ss;
    g_i_y_ss=g_i_ss/gdp_ss;
    tr_y_ss=tr_ss/params(63);
    oR_y_ss=params(48)/params(63);
    tR_y_ss=t_revenue_ss/params(63);
    S_y_ss=spending_ss/params(63);
    primary_balance_y_ss=(t_revenue_ss+params(48)-spending_ss)/params(63);
    interest_y_ss=params(64)*(params(49)*params(18)-1)/params(45)/params(63);
    R_y_ss=revenue_ss/params(63);
    xi_a_ss=params(18)^4-1;
    w_r_ss=w_ss/params(57);
    gdp_nco_ss=pH_ss*yH_ss/params(57);
    tau_c_y_ss=c_ss*tau_c_ss*params(57)/params(63);
    tau_n_y_ss=params(55)*(1-params(13))*tau_n_ss*w_ss/params(63);
    tau_k_y_ss=k_ss*tau_k_ss*(rK_ss-params(6))/params(45)/params(63);
    R_ss=params(49)*params(18);
    params(24)=g_c_ss;
    params(25)=g_i_ss;
    params(26)=tr_ss;
    ys_(70)=tr_ss;
    ys_(68)=g_c_ss;
    ys_(69)=g_i_ss;
    ys_(67)=tau_k_ss;
    ys_(65)=tau_c_ss;
    ys_(66)=tau_n_ss;
    ys_(1)=lam_o_ss;
    ys_(2)=c_hat_o_ss;
    ys_(3)=c_o_ss;
    ys_(4)=params(55);
    ys_(5)=i_o_ss;
    ys_(6)=k_o_ss;
    ys_(7)=f_star_o_ss;
    ys_(8)=Theta_o_ss;
    ys_(9)=chitil_o_ss;
    ys_(10)=lam_r_ss;
    ys_(11)=c_hat_r_ss;
    ys_(12)=c_r_ss;
    ys_(13)=params(56);
    ys_(14)=Theta_r_ss;
    ys_(15)=chitil_r_ss;
    ys_(16)=c_ss;
    ys_(17)=params(67);
    ys_(18)=i_ss;
    ys_(19)=k_ss;
    ys_(20)=params(65);
    ys_(21)=q_ss;
    ys_(22)=w_ss;
    ys_(23)=rK_ss;
    ys_(24)=params(63);
    ys_(25)=yC_ss;
    ys_(26)=yF_ss;
    ys_(27)=yH_ss;
    ys_(28)=xF_ss;
    ys_(29)=xH_ss;
    ys_(30)=xHstar_ss;
    ys_(31)=pi_ss;
    ys_(32)=pH_ss;
    ys_(33)=params(57);
